import boto3
import json

def extract_document_layout(file_path):
    with open(file_path, 'rb') as f:
        document = f.read()

    textract = boto3.client('textract')

    response = textract.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['LAYOUT', 'TABLES']
    )

    blocks = response['Blocks']

    layout_elements = {
        'pages': [],
        'lines': [],
        'words': [],
        'tables': [],
        'cells': [],
        'layout_elements': []
    }

    for block in blocks:
        block_type = block['BlockType']
        block_info = {
            'Id': block['Id'],
            'Text': block.get('Text', ''),
            'Confidence': block.get('Confidence', 0.0),
            'Geometry': block['Geometry'],
            'Relationships': block.get('Relationships', [])
        }
        if block_type == 'PAGE':
            layout_elements['pages'].append(block_info)
        elif block_type == 'LINE':
            layout_elements['lines'].append(block_info)
        elif block_type == 'WORD':
            layout_elements['words'].append(block_info)
        elif block_type == 'TABLE':
            layout_elements['tables'].append(block_info)
        elif block_type == 'CELL':
            layout_elements['cells'].append(block_info)
        elif block_type in ['LAYOUT_TITLE', 'LAYOUT_SECTION_HEADER', 'LAYOUT_HEADER', 'LAYOUT_FOOTER', 'LAYOUT_LIST_ITEM']:
            layout_elements['layout_elements'].append({**block_info, 'LayoutType': block_type})

    return layout_elements
